import json
from pathlib import Path
recs=[json.loads(l) for l in open("results/runs.jsonl") if l.strip()]
def py(r): return (r.get("versions") or {}).get("python","")
# dense seed-0 parent artifact for precision_size_latency: latest factorial dense_fp32? Actually "dense seed-0 parent's artifact bytes and latency from the latest factorial dense_fp32 row"
fact={}
for r in recs:
    if r.get("part")=="C" and r.get("phase")=="factorial" and r.get("status")=="ok" and py(r).startswith("3.12"):
        fact[(r["architecture"],r["method"])]=r
for k,r in sorted(fact.items()):
    print(k, r["artifact_bytes"], (r.get("latency") or {}).get("batch_256",{}).get("median_ms") or (r.get("latency") or {}).get("full_graph",{}).get("median_ms"))
prec={}
for r in recs:
    if r.get("part")=="C" and r.get("phase")=="precision" and r.get("status")=="ok" and py(r).startswith("3.12"):
        prec[(r["architecture"],r["method"])]=r
for k,r in sorted(prec.items()):
    lat=(r.get("latency") or {}).get("batch_256",{}).get("median_ms") or (r.get("latency") or {}).get("full_graph",{}).get("median_ms")
    print(k, r["artifact_bytes"], lat)
EOF

